Your definition of a hot spell
There is no single definition of a heatwave. Set your own: a hot spell is a run of days on which the daily maximum reaches the threshold, for at least the given number of days in a row. The chart counts them in every year; the line is a 15-year rolling mean.

viewof threshold = Inputs.range([25, 35], {value: 30, step: 0.5, label: "Threshold (°C)"})
viewof minDays = Inputs.range([1, 7], {value: 3, step: 1, label: "At least (days in a row)"})
















spells = {
  const rows = transpose(days);
  const byYear = new Map(annual.year.map((y) =&gt; [y, 0]));
  let run = 0, year = null;
  const close = () =&gt; { if (run &gt;= minDays && byYear.has(year)) byYear.set(year, byYear.get(year) + 1); run = 0; };
  for (const d of rows) {
    if (d.year !== year) { close(); year = d.year; }
    if (d.tmax_c &gt;= threshold) run += 1; else close();
  }
  close();
  const out = Array.from(byYear, ([year, n]) =&gt; ({year, n}));
  return out.map((d, i) =&gt; ({...d, mean: d3.mean(out.slice(Math.max(0, i - 7), i + 8), (e) =&gt; e.n)}));
}
spellsEarly = d3.mean(spells.filter((d) =&gt; d.year &gt;= 1951 && d.year &lt;= 1980), (d) =&gt; d.n)
spellsLate = d3.mean(spells.filter((d) =&gt; d.year &gt;= 1996 && d.year &lt;= 2025), (d) =&gt; d.n)























