  input.setAttribute("aria-label", label);
  const el = html`&lt;label class="tl-ctl"&gt;&lt;span class="tl-ctl-head"&gt;&lt;span&gt;${label}&lt;/span&gt;${out}&lt;/span&gt;${input}&lt;/label&gt;`;
  const update = () =&gt; { el.value = +input.value; out.innerHTML = fmt(+input.value); };
  input.addEventListener("input", update);   // runs before the event bubbles up to the label
  update();
  return el;
}

function choice({options, value, label}) {
  const sel = html`&lt;select&gt;${options.map(([v, t]) =&gt; html`&lt;option value=${v}&gt;${t}&lt;/option&gt;`)}&lt;/select&gt;`;
  sel.value = String(value);
  sel.setAttribute("aria-label", label);
  const el = html`&lt;label class="tl-ctl"&gt;&lt;span class="tl-ctl-head"&gt;&lt;span&gt;${label}&lt;/span&gt;&lt;/span&gt;${sel}&lt;/label&gt;`;
  const update = () =&gt; { el.value = options.find(([v]) =&gt; String(v) === sel.value)[0]; };
  sel.addEventListener("input", update);
  update();
  return el;
}
